using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.Json;
using System.IO.Compression;
using System.Collections.Generic;
namespace KingswayWorkshop;
public static class SelfTests {
 public static object Run(Store store){var assertions=new List<object>();void Check(bool condition,string name){assertions.Add(new{name,passed=condition});if(!condition)throw new Exception("FAIL: "+name);}string current=Game.Hash(Path.Combine(store.GameRoot,"data.win"));var active=store.Active();var sources=store.List();active=active.Select(m=>sources.FirstOrDefault(p=>p.Id==m.Id)??m).ToList();Check(active.Count>0,"At least one managed mod available");
  store.Build();string first=Game.Hash(store.LastBuild);int objects;using(var game=new Game(store.LastBuild))objects=game.Data.GameObjects.Count;store.Build();Check(first==Game.Hash(store.LastBuild),"Repeated builds are byte-for-byte deterministic");using(var game=new Game(store.LastBuild)){Check(game.Data.GameObjects.Count==objects,"Rebuild does not duplicate objects");Check(!game.Data.Code.Any(x=>x.Name.Content.Contains("v2_test")),"Release has no test instrumentation");Check(game.Data.GeneralInfo.Name.Content=="Kingsway","Release keeps original save namespace");}
  Manifest Clone(Manifest m){var c=JsonSerializer.Deserialize<Manifest>(Json.Text(m),Json.Options)!;c.Directory=m.Directory;return c;}
  var sample=Clone(active[0]);sample.Enemies[0].Loot.Add(new(){Item="obj_PotionAntidote",Chance=101});Check(Validation.Check(new(){sample},store.Catalog).Any(e=>e.Field=="loot.chance"&&e.Mod==sample.Id&&e.Enemy==sample.Enemies[0].Id),"Invalid percentage reports mod, enemy, field and value");
  Check(Validation.Check(new(){active[0],Clone(active[0])},store.Catalog).Any(e=>e.Field=="id"),"Duplicate mod IDs rejected");sample=Clone(active[0]);sample.Enemies[0].Components.Add(new(){Enemy=sample.Enemies[0].Id});Check(Validation.Check(new(){sample},store.Catalog).Any(e=>e.Message.Contains("cycle")),"Static component cycles rejected");sample=Clone(active[0]);sample.Overrides.Add(new(){Slot="obj_Skeleton",Enemy=sample.Enemies[0].Id});Check(Validation.Check(new(){sample},store.Catalog).Any(e=>e.Field=="overrides.slot"),"Slots without a reviewed adapter rejected");
  var firstMod=Clone(active[0]);firstMod.Overrides.Add(new(){Slot="obj_Brogt",Enemy=firstMod.Enemies[0].Id});var secondMod=Clone(active[0]);secondMod.Id="conflict_probe";secondMod.Overrides.Add(new(){Slot="obj_Brogt",Enemy=secondMod.Enemies[0].Id});Check(Validation.Check(new(){firstMod,secondMod},store.Catalog).Any(e=>e.Message.Contains("multiple mods")),"Boss slot conflicts rejected before compilation");
  bool unknown=false;try{JsonSerializer.Deserialize<Manifest>("{\"schemaVersion\":2,\"misspelledField\":1}",Json.Options);}catch(JsonException){unknown=true;}Check(unknown,"Unknown schema fields fail loudly");sample=Clone(active[0]);sample.SchemaVersion=4;Check(Validation.Check(new(){sample},store.Catalog).Count>0,"Future schema version rejected");
  string testRoot=Path.Combine(store.Root,"Builds","integration-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(testRoot,"Catalog"));File.Copy(Path.Combine(store.Root,"Catalog","catalog.json"),Path.Combine(testRoot,"Catalog","catalog.json"));var sandbox=new Store(testRoot,store.GameRoot);byte[] archive=store.Export(active[0].Id);string imported=sandbox.Import(archive);Check(sandbox.List("Mods").Any(x=>x.Id==imported),"Exported archive imports into managed Mods");Check(sandbox.ValidateProject(imported).Count==0,"Imported archive validates");bool duplicate=false;try{sandbox.Import(archive);}catch{duplicate=true;}Check(duplicate,"Import refuses silently overwriting an existing mod");
  using var stream=new MemoryStream();using(var zip=new ZipArchive(stream,ZipArchiveMode.Create,true)){var entry=zip.CreateEntry("../escape.txt");using var writer=new StreamWriter(entry.Open());writer.Write("invalid");}bool traversal=false;try{sandbox.Import(stream.ToArray());}catch{traversal=true;}Check(traversal&&!File.Exists(Path.Combine(testRoot,"escape.txt")),"Traversal archive fails without writing outside staging");
  string broken=Path.Combine(testRoot,"Projects","broken");Directory.CreateDirectory(broken);var fail=new Manifest{Id="broken",Directory=broken,Enemies=new(){new(){AdvancedGml="broken.gml"}}};File.WriteAllText(Path.Combine(broken,"broken.gml"),"this is deliberately invalid GML !!!");bool failed=false;try{using var game=new Game(store.Original);new Compiler(game,store.Catalog,store.Root).Build(new(){fail},Path.Combine(testRoot,"broken.win"));}catch{failed=true;}Check(failed&&Game.Hash(store.LastBuild)==first&&Game.Hash(Path.Combine(store.GameRoot,"data.win"))==current,"Failed compile preserves working build and active game bytes");
  Check(Game.Hash(store.Original)==Game.OriginalHash,"Pristine backup remains verified");Check(Game.Hash(Path.Combine(store.Root,"Recovery","v1-verified.win"))==JsonDocument.Parse(File.ReadAllText(Path.Combine(store.Root,"Recovery","v1-installed.json"))).RootElement.GetProperty("sha256").GetString(),"V1 recovery bytes remain verified");
  string fakeGame=Path.Combine(testRoot,"transaction-game"),fakeRoot=Path.Combine(fakeGame,"Workshop");Directory.CreateDirectory(Path.Combine(fakeGame,"KingswayModding","backup"));Directory.CreateDirectory(Path.Combine(fakeRoot,"Catalog"));File.Copy(store.Original,Path.Combine(fakeGame,"KingswayModding","backup","data.win"));File.Copy(Path.Combine(store.Root,"Catalog","catalog.json"),Path.Combine(fakeRoot,"Catalog","catalog.json"));File.WriteAllBytes(Path.Combine(fakeGame,"data.win"),new byte[]{42,43,44});var transactions=new Store(fakeRoot,fakeGame);string external=Game.Hash(Path.Combine(fakeGame,"data.win"));bool rejected=false;try{transactions.Install(true);}catch(Exception ex){rejected=ex.Message.Contains("External change");}Check(rejected&&Game.Hash(Path.Combine(fakeGame,"data.win"))==external,"Unknown external game bytes are preserved and restoration is blocked");
  File.Copy(store.Original,Path.Combine(fakeGame,"data.win"),true);File.Copy(store.LastBuild,transactions.LastBuild);File.Copy(store.LastBuild+".json",transactions.LastBuild+".json");using(var append=new FileStream(transactions.LastBuild,FileMode.Append))append.WriteByte(42);rejected=false;try{transactions.Install();}catch(Exception ex){rejected=ex.Message.Contains("Unverified");}Check(rejected&&Game.Hash(Path.Combine(fakeGame,"data.win"))==Game.OriginalHash,"Changed build bytes fail verification before replacement");
  File.WriteAllBytes(transactions.Original,new byte[]{42});rejected=false;try{transactions.Install(true);}catch{rejected=true;}Check(rejected&&Game.Hash(Path.Combine(fakeGame,"data.win"))==Game.OriginalHash,"Unsupported original checksum blocks restoration without changing active data");
  bool required=false;try{JsonSerializer.Deserialize<Manifest>("{\"schemaVersion\":2,\"id\":\"missing_enemies\"}",Json.Options);}catch(JsonException){required=true;}Check(required,"Missing required manifest fields are rejected");
  bool LootValid(Loot loot){var m=Clone(active[0]);m.Enemies[0].Loot=new(){loot};return Validation.Check(new(){m},store.Catalog).Count==0;}
  Check(LootValid(new(){Item="obj_BrokenSword",Enchantment="selected",Enchantments=new(){new(){Stat="strength",Amount=7},new(){Stat="vampirismPercent",Amount=12}}}),"Selected equipment bonuses validate with explicit amounts");
  Check(!LootValid(new(){Item="obj_PotionAntidote",Enchantment="random"}),"Consumable enchantments rejected");
  Check(!LootValid(new(){Item="obj_BrokenSword",Enchantment="selected"}),"Empty guaranteed bonus selection rejected");
  Check(!LootValid(new(){Item="obj_BrokenSword",Enchantment="selected",Enchantments=new(){new(){Stat="unknown"}}}),"Unknown enchantment rejected");
  Check(!LootValid(new(){Item="obj_BrokenSword",Enchantment="selected",Enchantments=new(){new(),new()}}),"Duplicate enchantments rejected");
  Check(!LootValid(new(){Item="obj_BrokenSword",Enchantment="selected",Enchantments=new(){new(){Amount=0}}}),"Zero enchantment amount rejected");
  Check(!LootValid(new(){Item="obj_BrokenSword",Enchantment="random",Enchantments=new(){new()}}),"Selected bonuses require selected mode");
  Check(JsonSerializer.Deserialize<Loot>("{\"item\":\"obj_BrokenSword\"}",Json.Options).Enchantment=="native","Older manifests retain native enchantment behavior");
  sample=Clone(active[0]);sample.Enemies[0].Loot=new(){new(){Item="obj_BrokenSword",Enchantment="selected",Enchantments=new(){new(){Stat="strength",Amount=7}}}};sandbox.Save(sample);var enriched=sandbox.Export(sample.Id);var zipCheck=Path.Combine(testRoot,"roundtrip");Directory.CreateDirectory(Path.Combine(zipCheck,"Catalog"));File.Copy(Path.Combine(store.Root,"Catalog","catalog.json"),Path.Combine(zipCheck,"Catalog","catalog.json"));var secondStore=new Store(zipCheck,store.GameRoot);secondStore.Import(enriched);Check(secondStore.List()[0].Enemies[0].Loot[0].Enchantments[0].Amount==7,"Enchantment selections survive ZIP export and import");
  void CopyFixtureAssets(Manifest m){foreach(var file in Directory.GetFiles(active[0].Directory,"*",SearchOption.AllDirectories)){var rel=Path.GetRelativePath(active[0].Directory,file);if(rel=="mod.json")continue;var dest=Validation.Within(m.Directory,rel,false);Directory.CreateDirectory(Path.GetDirectoryName(dest));File.Copy(file,dest,true);}}
  bool EnemyValid(Action<Enemy> change){var m=Clone(active[0]);change(m.Enemies[0]);return Validation.Check(new(){m},store.Catalog).Count==0;}
  Check(EnemyValid(e=>e.Actions=new(){new(){Kind="wait",WaitMin=.25,WaitMax=.25}}),"Equal decimal waits accepted");
  Check(!EnemyValid(e=>e.Actions=new(){new(){Kind="wait",WaitMin=-1}}),"Negative waits rejected");
  Check(!EnemyValid(e=>e.Actions=new(){new(){Kind="wait",WaitMin=1,WaitMax=.5}}),"Inverted wait bounds rejected");
  Check(!EnemyValid(e=>e.Actions=new(){new(){Repeat=100,Children=new(){new(){Repeat=100}}}}),"Explosive nested repeats rejected");
  Check(EnemyValid(e=>{e.Movement.Profile="";e.Movement.Points=new(){new(){X=-1,Y=2},new(){X=2,Y=-1}};}),"Offscreen coordinates from minus one through two accepted");
  Check(!EnemyValid(e=>{e.Movement.Profile="";e.Movement.Points=new(){new(){X=-1.01},new()};}),"Coordinates outside supported range rejected");
  Check(!EnemyValid(e=>{e.Movement.Profile="";e.Movement.Points=new(){new(),new()};e.Movement.LoopStart=3;}),"Loop index must refer to an existing point");
  Check(!EnemyValid(e=>e.SpawnSound="missing_sound"),"Unknown spawn sound rejected");
  Check(!EnemyValid(e=>e.Music="missing_music"),"Unknown encounter music rejected");
  Check(!EnemyValid(e=>e.Actions=new(){new(){Kind="sound",Asset="missing_sound"}}),"Unknown sound action rejected");
  Check(EnemyValid(e=>e.SpawnSound=store.Catalog.SoundNames.First()),"Existing native sound accepted");
  bool badPng=false;try{AssetValidation.Png(new byte[]{137,80,78,71,13,10,26,10,0,0,0,13,73,72,68,82,0,0,0,1,0,0,0,1});}catch{badPng=true;}Check(badPng,"Truncated PNG is rejected by image decoding");
  sample=Clone(active[0]);sample.Id="empty_roundtrip";sample.Enemies.Clear();sample.Overrides.Clear();sample.Patches.Clear();sandbox.Save(sample);CopyFixtureAssets(sample);secondStore.Import(sandbox.Export(sample.Id));Check(secondStore.List().Single(x=>x.Id==sample.Id).Enemies.Count==0,"Deleting the last enemy survives save, export, and reopen");
  sample=Clone(active[0]);sample.Id="audio_roundtrip";sample.Overrides.Clear();sample.Patches.Clear();sandbox.Save(sample);CopyFixtureAssets(sample);
  string wav=Directory.GetFiles(Path.Combine(store.Root,"Tests","Fixture"),"*.wav",SearchOption.AllDirectories).First();
  var importedAudio=AudioAssets.Import(sandbox,sample.Id,"probe","sound",".wav",File.ReadAllBytes(wav));
  importedAudio.Enemies[0].SpawnSound="probe";sandbox.Save(importedAudio);secondStore.Import(sandbox.Export(sample.Id));var reopened=secondStore.List().Single(x=>x.Id==sample.Id);Check(reopened.Enemies[0].SpawnSound=="probe"&&File.Exists(Validation.Within(reopened.Directory,reopened.Audio["probe"].File)),"Custom audio and references survive archive roundtrip");
  var musicImport=AudioAssets.Import(sandbox,sample.Id,"music_probe","music",".wav",File.ReadAllBytes(wav));Check(musicImport.Audio["music_probe"].File.EndsWith(".ogg")&&File.Exists(Validation.Within(musicImport.Directory,musicImport.Audio["music_probe"].Original)),"WAV music converts before gameplay and preserves its original");
  musicImport.Enemies[0].SpawnSound="music_probe";Check(Validation.Check(new(){musicImport},store.Catalog).Any(x=>x.Field=="spawnSound"),"Music cannot be selected as a sound effect");
  sample=Clone(active[0]);sample.Id="image_isolation";sample.Enemies=new(){new(){Id="first",Image="portrait"},new(){Id="second",Image="portrait"}};sample.Overrides.Clear();sample.Patches.Clear();sandbox.Save(sample);CopyFixtureAssets(sample);
  sample.Assets["portrait"]="test-portrait.png";File.Copy(Path.Combine(store.Root,"Tests","Fixture","portrait.png"),Path.Combine(sample.Directory,"test-portrait.png"),true);sandbox.Save(sample);
  string legacy=Validation.Within(sample.Directory,sample.Assets["portrait"]),legacyHash=Game.Hash(legacy);
  byte[] firstPng=File.ReadAllBytes(legacy),secondPng=File.ReadAllBytes(Path.Combine(store.Root,"Catalog","images","spr_Skeleton_0.png"));
  var imageOne=AssetUploads.Image(sandbox,sample.Id,"portrait",firstPng);var imageTwo=AssetUploads.Image(sandbox,sample.Id,"portrait",secondPng);
  var images=sandbox.List().Single(x=>x.Id==sample.Id);
  Check(imageOne.Name!=imageTwo.Name&&imageOne.File!=imageTwo.File&&Game.Hash(Validation.Within(images.Directory,imageOne.File))==legacyHash,"PNG uploads get independent names and preserve the first upload bytes");
  Check(Game.Hash(legacy)==legacyHash&&images.Enemies.All(e=>e.Image=="portrait")&&images.Assets["portrait"]==sample.Assets["portrait"],"Uploading never overwrites a legacy portrait or changes existing enemy references");
  images.Enemies[0].Image=imageOne.Name;images.Enemies[1].Image=imageTwo.Name;sandbox.Save(images);
  int beforeImages=Directory.GetFiles(images.Directory,"*.png").Length;bool invalidUpload=false;try{AssetUploads.Image(sandbox,images.Id,"portrait",new byte[]{1,2,3});}catch{invalidUpload=true;}
  Check(invalidUpload&&Directory.GetFiles(images.Directory,"*.png").Length==beforeImages,"Invalid PNG upload creates no asset and preserves saved project contents");
  var soundOne=AssetUploads.Audio(sandbox,images.Id,"sound","sound",".wav",File.ReadAllBytes(wav));var soundTwo=AssetUploads.Audio(sandbox,images.Id,"sound","sound",".wav",File.ReadAllBytes(wav));
  images=sandbox.List().Single(x=>x.Id==images.Id);images.Enemies[0].SpawnSound=soundOne.Name;images.Enemies[1].SpawnSound=soundTwo.Name;sandbox.Save(images);
  Check(soundOne.Name!=soundTwo.Name&&images.Audio.ContainsKey(soundOne.Name)&&images.Audio.ContainsKey(soundTwo.Name),"Duplicate audio upload names cannot reassign another enemy sound");
  secondStore.Import(sandbox.Export(images.Id));var imageRoundtrip=secondStore.List().Single(x=>x.Id==images.Id);
  Check(imageRoundtrip.Enemies[0].Image==imageOne.Name&&imageRoundtrip.Enemies[1].Image==imageTwo.Name&&Game.Hash(Validation.Within(imageRoundtrip.Directory,imageOne.File))==legacyHash&&imageRoundtrip.Enemies[1].SpawnSound==soundTwo.Name,"Independent portraits and audio survive archive export and import");
  Check(!Json.Text(imageOne).Contains("enemies")&&!Json.Text(soundOne).Contains("enemies"),"Upload responses contain asset metadata rather than stale enemy snapshots");
  using(var uploadedGame=new Game(store.Original))new Compiler(uploadedGame,store.Catalog,store.Root).Build(new(){images},Path.Combine(testRoot,"uploaded-assets.win"));
  Check(File.Exists(Path.Combine(testRoot,"uploaded-assets.win")),"Freshly uploaded portrait and audio identifiers compile into native game data");
  ActionTests.Run(store,Check);MotionTests.Run(store,Check);MinimizeTests.Run(store,Check);
  var result=new{passed=true,assertions,releaseSha256=first,activeUnchanged=current==Game.Hash(Path.Combine(store.GameRoot,"data.win"))};Json.Save(Path.Combine(store.Root,"Evidence","backend-tests.json"),result);return result;
 }
